function createEnv(sdk) {
  var GOAL = 1100;
  var PLAYER_Y = 438;
  var PLAYER_R = 13;
  var MAX_ROCKS = 100;

  var rng, rocks, playerX, t, done;
  var terms = [0, 0, 0];
  var obs = new Array(18);

  function reset(seed) {
    rng = sdk.rng(seed);
    rocks = [];
    playerX = 400;
    t = 0;
    done = false;
    terms[0] = 0;
    terms[1] = 0;
    terms[2] = 0;
  }

  function step(action) {
    if (done) return;

    var move = action === 0 ? -1 : (action === 2 ? 1 : 0);
    playerX = sdk.clamp(playerX + move * 8.5, 24, 776);

    var progress = Math.min(1, t / GOAL);
    var spawnChance = 0.028 + 0.055 * progress;
    var rockSpeed = 3.2 + 2.6 * progress;

    if (rocks.length < MAX_ROCKS && rng.next() < spawnChance) {
      var radius = rng.range(13, 23);
      rocks.push({
        x: rng.range(30 + radius, 770 - radius),
        y: -radius,
        vx: rng.range(-0.75, 0.75),
        speed: rockSpeed * rng.range(0.82, 1.18),
        r: radius
      });
    }

    var hit = false;
    for (var i = rocks.length - 1; i >= 0; i--) {
      var rock = rocks[i];
      rock.y += rock.speed;
      rock.x += rock.vx;

      if (rock.x < rock.r + 20) {
        rock.x = rock.r + 20;
        rock.vx = Math.abs(rock.vx);
      } else if (rock.x > 780 - rock.r) {
        rock.x = 780 - rock.r;
        rock.vx = -Math.abs(rock.vx);
      }

      var dx = playerX - rock.x;
      var dy = PLAYER_Y - rock.y;
      var reach = PLAYER_R + rock.r;
      if (dx * dx + dy * dy <= reach * reach) hit = true;

      if (rock.y > 550) rocks.splice(i, 1);
    }

    if (hit) {
      terms[2] += 1;
      t += 1;
      done = true;
      return;
    }

    terms[0] += 1 / GOAL;

    var nearestGap = 100;
    for (var j = 0; j < rocks.length; j++) {
      var r = rocks[j];
      var timeToLane = (PLAYER_Y - r.y) / r.speed;
      if (timeToLane >= 0 && timeToLane <= 60) {
        var predictedX = sdk.clamp(r.x + r.vx * timeToLane, 20 + r.r, 780 - r.r);
        var gap = Math.abs(playerX - predictedX) - PLAYER_R - r.r;
        if (gap < nearestGap) nearestGap = gap;
      }
    }
    var clearance = sdk.clamp((nearestGap + 8) / 90, 0, 1);
    terms[1] += clearance / GOAL;

    t += 1;
    if (t >= GOAL) done = true;
  }

  function observe() {
    obs[0] = (playerX - 400) / 376;
    obs[1] = Math.min(1, t / GOAL);

    var chosen = [];
    for (var slot = 0; slot < 4; slot++) {
      var bestIndex = -1;
      var bestY = -100000;
      for (var i = 0; i < rocks.length; i++) {
        var alreadyChosen = false;
        for (var k = 0; k < chosen.length; k++) {
          if (chosen[k] === i) alreadyChosen = true;
        }
        if (!alreadyChosen && rocks[i].y > bestY) {
          bestY = rocks[i].y;
          bestIndex = i;
        }
      }

      var base = 2 + slot * 4;
      if (bestIndex < 0) {
        obs[base] = 0;
        obs[base + 1] = 1;
        obs[base + 2] = 0;
        obs[base + 3] = 0;
      } else {
        chosen.push(bestIndex);
        var rock = rocks[bestIndex];
        obs[base] = sdk.clamp((rock.x - playerX) / 400, -1, 1);
        obs[base + 1] = sdk.clamp((PLAYER_Y - rock.y) / 500, -1, 1);
        obs[base + 2] = sdk.clamp(rock.vx / 1.5, -1, 1);
        obs[base + 3] = sdk.clamp(rock.r / 25, 0, 1);
      }
    }
    return obs;
  }

  function render(draw, ghost) {
    if (!ghost) {
      draw.clear(sdk.colors.bg);
      draw.line(18, PLAYER_Y + 22, 782, PLAYER_Y + 22, sdk.colors.dim, 2);
      for (var i = 0; i < rocks.length; i++) {
        draw.circle(rocks[i].x, rocks[i].y, rocks[i].r, sdk.colors.warn);
        draw.circle(rocks[i].x - rocks[i].r * 0.25, rocks[i].y - rocks[i].r * 0.25, rocks[i].r * 0.22, sdk.colors.dim);
      }
      draw.text("STORM " + Math.round(Math.min(1, t / GOAL) * 100) + "%", 24, 32, sdk.colors.fg, 18);
    }
    draw.circle(playerX, PLAYER_Y, PLAYER_R, sdk.colors.accent);
    draw.circle(playerX, PLAYER_Y - 3, 5, sdk.colors.good);
  }

  function humanAct(input) {
    if (input.held.has("ArrowLeft")) return 0;
    if (input.held.has("ArrowRight")) return 2;
    return 1;
  }

  return {
    reset: reset,
    step: step,
    observe: observe,
    get done() { return done; },
    terms: terms,
    render: render,
    humanAct: humanAct
  };
}
